{
  "lecture": [
    {
      "etiquette": "F36",
      "R1": {
        "valeur": 1,
        "passage": "à nombre de tirages frais total égal, au moins 30 % de lois fausses promues en moins aux générations 5 à 8 que la réserve réutilisée telle quelle, sans perte de couverture"
      },
      "R2": {
        "valeur": 1,
        "passage": "lois fausses promues par génération et composantes plantées couvertes (oracle)"
      },
      "R3": {
        "valeur": 0,
        "motif": "Le remplacement des tirages frais par une réserve réutilisée et bruitée ne maintient pas explicitement la garantie des valeurs e contre le nul contenant l'archive."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche affirme une garantie de généralisation et un contrôle des comparaisons multiples, mais ne précise pas contre quel nul ils restent démontrables."
      },
      "R5": {
        "valeur": 0,
        "motif": "Le mécanisme ne fixe ni le seuil, ni la distribution et l'amplitude du bruit, ni leur articulation avec les valeurs e et la promotion."
      },
      "R6": {
        "valeur": 0,
        "motif": "Des témoins sont nommés, mais la mention d'une simulation sur processeur ne donne aucun ordre de grandeur du coût de l'expérience décisive."
      },
      "R7": {
        "valeur": 1,
        "passage": "Pour l'empêcher, le juge ne consulte la réserve qu'à travers un mécanisme à seuil bruité"
      },
      "N": {
        "valeur": "C11",
        "passage_fiche": "La réserve supporte alors un grand nombre de consultations adaptatives sans surajustement.",
        "passage_catalogue": "**Réutiliser une réserve de test** de façon adaptative, de nombreuses fois, sans surajustement à la réserve, par un mécanisme qui ne la consulte qu'à travers un seuil bruité."
      }
    },
    {
      "etiquette": "F37",
      "R1": {
        "valeur": 1,
        "passage": "À coût total (appels aux modèles et tirages d'épisodes du monde) strictement égal, l'allocation séquentielle augmente de 30 % le nombre de composantes plantées vraies couvertes par l'oracle"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle du nombre total de composantes plantées vraies couvertes (D2) et de fausses promotions rapportés au coût total consommé (jetons et épisodes tirés)"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les valeurs e et les retenues du juge déterminent quelles courses continuent à recevoir des appels de proposeurs, faisant du verdict du juge un signal de sélection."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La demande ne définit ni la valeur finale des groupes arrêtés après l'amorçage ni la règle de partage des crédits entre les courses bénéficiaires."
      },
      "R6": {
        "valeur": 1,
        "passage": "sur processeur seul (zéro dépense d'appel) en simulant le découpage 10 % / 90 % des tirages et la règle d'arrêt sur les traces d'épisodes déjà enregistrées des courses précédentes."
      },
      "R7": {
        "valeur": 0,
        "motif": "La validité de l'arrêt optionnel ne montre pas que les courses récemment promues contiennent davantage de composantes vraies accessibles que les courses arrêtées, donc ne détermine pas le signe du gain."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F38",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues augmente d'au moins 30 % par rapport à la composition monolithique à une passe"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes, les représentants et les retenues, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "La maximisation d'une distance numérique à l'archive pour imposer les cibles réintroduit une prime numérique de nouveauté sans nommer l'objection ni expliquer pourquoi elle ne s'appliquerait pas."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "un algorithme glouton maximisant à chaque pas la distance de Jaccard minimale aux tuples déjà sélectionnés et à ceux de l'archive"
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dizaines de dollars d'appels) : comparer par l'oracle la couverture des 6 cartes issues du couplage Passe 1 + Passe 2 contre les 6 cartes d'un appel monolithique à coût supérieur ou égal."
      },
      "R7": {
        "valeur": 0,
        "motif": "La déduplication syntaxique et la distance entre tuples ne relient pas leur sélection à davantage de composantes vraies, et peuvent aussi écarter des traits pertinents au profit de traits de bruit."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F39",
      "R1": {
        "valeur": 1,
        "passage": "à calcul égal, au moins 20 % de composantes plantées couvertes en plus qu'une trajectoire unique"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes (oracle, après la course) ; témoins à calcul égal : trajectoire unique, et meilleur de N trajectoires indépendantes"
      },
      "R3": {
        "valeur": 0,
        "motif": "La trajectoire poursuivie est sélectionnée selon le nombre de cartes promues par le juge, contrairement à l'interdiction de sélectionner la composition sur ses verdicts."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "La demande laisse indéterminés le nombre K de trajectoires et l'horizon H, nécessaires pour fixer la procédure de dédoublement et de reprise."
      },
      "R6": {
        "valeur": 0,
        "motif": "Les témoins sont nommés, mais un coût exprimé comme K fois un coût non quantifié sur un horizon non fixé ne borne pas l'expérience décisive."
      },
      "R7": {
        "valeur": 0,
        "motif": "Le mécanisme invoque la suppression de l'ancrage conversationnel alors que les faits indiquent que chaque appel de proposeur se fait déjà en session neuve sans historique."
      },
      "N": {
        "valeur": "C5",
        "passage_fiche": "Après un horizon fixe de générations, la course continue depuis la trajectoire qui a obtenu le plus de cartes promues par le juge ; les autres sont abandonnées.",
        "passage_catalogue": "après un horizon fixe, on **continue depuis la trajectoire au meilleur score**"
      }
    }
  ]
}
